edits.before:
initialize() {
  try {
    super.initialize();

    this._handleFocus();
    this._handleClick();
    this._handleHover();
    this._handleKeydown();
    this._handleKeyup();
  } catch (error) {
    console.error(error);
  }
}

edits.after:
initialize() {
  try {
    super.initialize();

    this._handleFocus();
    this._handleClick();
    this._handleHover();
    this._handleKeydown();
    this._handleKeyup();

    // Close dropdown when focus leaves the menu
    this.dom.menu.addEventListener('focusout', (event) => {
      if (!this.dom.menu.contains(event.relatedTarget)) {
        this.closeChildren();
      }
    });
  } catch (error) {
    console.error(error);
  }
}
